// Tests for the owner's scarlet sword (items/scarletSwordArt.ts, generated by
// tools/refs/scarlet-sword-from-ref.py): npm test.

import assert from 'node:assert/strict';
import { describe, it } from 'node:test';
import { renderSprite } from './compose';
import { gripPoint } from './grip';
import { SCARLET_SWORD } from './items/scarletSwordArt';
import { GRID, RES } from './raster';
import type { SpriteAppearance } from './types';
import type { DrawCtx } from './ctx';
import { weaponOf } from '../battle/units';
import { DEFAULT_CHARACTER } from '../data/shinobiData';

const look = (body: SpriteAppearance['body']): SpriteAppearance => ({
  ...DEFAULT_CHARACTER.appearance!,
  body,
  slots: { held: { id: 'held_scarlet_sword', colors: [] } },
  accessories: [],
  pixelEdits: [],
});

describe('scarlet sword', () => {
  it('is one whole picture: even rows, every character coloured, each in at most one colour slot, the pivot on the grip', () => {
    const t = SCARLET_SWORD;
    const w = t.rows[0].length;
    assert.ok(t.rows.every((r) => r.length === w));
    for (const r of t.rows) for (const ch of r) if (ch !== '.') assert.match(t.colors[ch] ?? '', /^#[0-9a-f]{6}$/, `'${ch}'`);
    for (const ch of Object.keys(t.colors)) assert.ok([t.blade, t.edge, t.guard].filter((s) => s.includes(ch)).length <= 1, `'${ch}'`);
    const [px, py] = t.pivot;
    assert.notEqual(t.rows[py][px], '.', 'the pivot sits on the grip');
    // 3 down for 2 across, so its lines step evenly
    assert.equal(t.angle, Math.round((Math.atan2(3, 2) * 180) / Math.PI * 100) / 100);
  });

  it('hangs at rest exactly as drawn: the blade below the fist is every pixel the template, on every body', () => {
    const t = SCARLET_SWORD;
    for (const body of ['male', 'female', 'bulky'] as const) {
      const f = renderSprite(look(body), 'idle', 0);
      const p = gripPoint({ rig: f.rig } as DrawCtx);
      const ax = Math.floor(p.x * RES);
      const ay = Math.floor(p.y * RES);
      let seen = 0;
      // From 12 rows under the grip down the blade is clear of the fist.
      for (let r = t.pivot[1] + 12; r < t.rows.length; r++) {
        for (let c = 0; c < t.rows[r].length; c++) {
          const ch = t.rows[r][c];
          if (ch === '.') continue;
          const x = ax + c - t.pivot[0];
          const y = ay + r - t.pivot[1];
          const i = (y * GRID + x) * 4;
          const hex = '#' + [0, 1, 2].map((k) => f.rgba[i + k].toString(16).padStart(2, '0')).join('');
          assert.equal(hex, t.colors[ch], `${body} row ${r} col ${c}`);
          seen++;
        }
      }
      assert.ok(seen > 150, `${body}: ${seen} pixels`);
    }
  });

  it('fights as a one-handed longsword', () => {
    const w = weaponOf({ ...DEFAULT_CHARACTER, appearance: look('male') });
    assert.deepEqual([w.dice, w.type, w.reach, w.held, !!w.twoHanded], ['1d8', 'Slashing', 1.5, true, false]);
  });
});
